package com.salespunch360.mobile.data

import com.salespunch360.mobile.BuildConfig
import java.util.concurrent.TimeUnit
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.Request
import okhttp3.OkHttpClient
import okhttp3.MultipartBody
import okhttp3.RequestBody.Companion.toRequestBody
import java.io.IOException

internal fun invalidateOnUnauthorized(status:Int,invalidate:()->Unit){if(status==401)invalidate()}
class ApiClient(private val session:SecureSession){
 companion object {
  private val sharedHttp=OkHttpClient.Builder().connectTimeout(15,TimeUnit.SECONDS).readTimeout(20,TimeUnit.SECONDS).writeTimeout(20,TimeUnit.SECONDS).retryOnConnectionFailure(true).build()
 }
 private val json=Json{ignoreUnknownKeys=true};private val http=sharedHttp;private val media="application/json".toMediaType()
 private suspend fun call(path:String,method:String="GET",body:String?=null,auth:Boolean=true)=withContext(Dispatchers.IO){val requestToken=if(auth)session.token() else null;val builder=Request.Builder().url(BuildConfig.API_BASE_URL+path).header("Accept","application/json");requestToken?.let{builder.header("Authorization","Bearer $it")};when(method){"POST"->builder.post((body?:"{}").toRequestBody(media));"PATCH"->builder.patch((body?:"{}").toRequestBody(media))};http.newCall(builder.build()).execute().use{val response=it.body?.string()?:"{}";if(!it.isSuccessful){val code=runCatching{json.parseToJsonElement(response).jsonObject["error"]?.jsonPrimitive?.content}.getOrNull();if(auth){if(it.code==401)session.invalidateIfCurrent(requestToken);if(it.code==403&&code=="FORBIDDEN")session.authorizationChanged()};val distance=runCatching{json.parseToJsonElement(response).jsonObject["distanceMeters"]?.jsonPrimitive?.content?.toDouble()}.getOrNull();throw ApiException(it.code,code,distance)};response}}
 private fun decodeBootstrap(raw:String,path:String=""):Bootstrap{val root=json.parseToJsonElement(raw).jsonObject;val payload=if(path.isEmpty())root else root[path]!!.jsonObject;return json.decodeFromJsonElement(Bootstrap.serializer(),payload)}
 private fun enc(value:String)=java.net.URLEncoder.encode(value,"UTF-8")
 suspend fun login(identifier:String,password:String):Bootstrap{val raw=call("api/v1/mobile/auth/login","POST",json.encodeToString(LoginRequest(identifier,password)),false);val root=json.parseToJsonElement(raw).jsonObject;val bootstrap=decodeBootstrap(raw,"bootstrap");session.save(root["accessToken"]!!.jsonPrimitive.content,bootstrap.user.id);return bootstrap}
 suspend fun bootstrap()=decodeBootstrap(call("api/v1/mobile/bootstrap"))
 suspend fun accountBootstrap(branchId:String?=null,companyWide:Boolean=false):AccountBootstrap{val query=when{companyWide->"?scope=all";branchId!=null->"?branchId=${enc(branchId)}";else->""};return json.decodeFromString(call("api/v1/mobile/account/bootstrap$query"))}
 suspend fun accountDashboard(branchId:String?=null,companyWide:Boolean=false):AccountDashboard{val query=when{companyWide->"?scope=all";branchId!=null->"?branchId=${enc(branchId)}";else->""};return json.decodeFromString(call("api/v1/mobile/account/dashboard$query"))}
 suspend fun accountMasterList(kind:String,q:String="",active:String="true",branchId:String?=null):List<AccountMasterRecord>{val query=buildList{if(q.isNotBlank())add("q=${enc(q)}");add("active=${enc(active)}");branchId?.let{add("branchId=${enc(it)}")}}.joinToString("&",prefix="?");return json.decodeFromString(call("api/v1/mobile/account/master-data/${enc(kind)}$query"))}
 suspend fun accountMasterOptions():AccountMasterOptions=json.decodeFromString(call("api/v1/mobile/account/master-data/customers?view=options"))
 suspend fun accountMasterDetail(kind:String,id:String):AccountPartyDetail=json.decodeFromString(call("api/v1/mobile/account/master-data/${enc(kind)}/${enc(id)}"))
 suspend fun saveAccountMaster(kind:String,id:String?,payload:kotlinx.serialization.json.JsonObject):AccountMasterRecord{val raw=call("api/v1/mobile/account/master-data/${enc(kind)}${id?.let{"/${enc(it)}"}.orEmpty()}",if(id==null)"POST" else "PATCH",payload.toString());return runCatching{json.decodeFromString<AccountMasterRecord>(raw)}.getOrElse{json.decodeFromString<AccountPartyDetail>(raw).record}}
 suspend fun dashboard(liveEmployee:String?=null,checkEmployee:String?=null):MobileDashboardContext{val q=buildList{liveEmployee?.let{add("liveEmployee=${enc(it)}")};checkEmployee?.let{add("checkEmployee=${enc(it)}")}}.joinToString("&");return json.decodeFromString(call("api/v1/mobile/dashboard${if(q.isBlank())"" else "?$q"}"))}
 suspend fun createWebSessionHandoff(redirectPath:String="/workspace/account")=json.decodeFromString<WebSessionHandoff>(call("api/v1/mobile/web-session","POST",json.encodeToString(WebSessionRequest(redirectPath))))
 suspend fun registerPush(installationId:String,fcmToken:String){call("api/v1/mobile/push","POST",json.encodeToString(buildJsonObject{put("installationId",installationId);put("fcmToken",fcmToken)}))};suspend fun logout(){try{call("api/v1/mobile/auth/logout","POST")}finally{session.clear()}};suspend fun changePassword(current:String,password:String,confirm:String)=call("api/v1/mobile/auth/password","POST",json.encodeToString(PasswordChangeRequest(current,password,confirm)))
 suspend fun attendance(action:String,location:LocationPayload?)=call("api/v1/mobile/attendance","POST",json.encodeToString(attendanceRequest(action,location)));suspend fun attendanceOverview()=json.decodeFromString<TeamAttendanceContext>(call("api/v1/mobile/attendance/overview"));suspend fun upload(point:LocationPayload)=call("api/v1/mobile/locations","POST",json.encodeToString(point))
 suspend fun employees()=json.decodeFromString<EmployeeContext>(call("api/v1/mobile/employees"))
 suspend fun createEmployee(request:CreateEmployeeRequest){val payload=buildJsonObject{put("role",request.role.name);put("name",request.name);put("email",request.email);request.phone?.let{put("phone",it)};put("password",request.password);put("confirmPassword",request.confirmPassword);if(request.role!=MobileRole.ADMIN){request.employeeCode?.let{put("employeeCode",it)};request.designation?.let{put("designation",it)};request.dateOfJoining?.let{put("dateOfJoining",it)};put("branchAccessScope",request.branchAccessScope);putJsonArray("branchIds"){request.branchIds.forEach{add(kotlinx.serialization.json.JsonPrimitive(it))}}};if(request.role==MobileRole.SALES)request.managerId?.let{put("managerId",it)};if(request.role==MobileRole.MANAGER)request.managerType?.let{put("managerType",it.name)}};call("api/v1/mobile/employees","POST",payload.toString())}
 suspend fun editEmployee(request:EditEmployeeRequest)=call("api/v1/mobile/employees","PATCH",json.encodeToString(request))
 suspend fun changeEmployeeRole(request:ChangeEmployeeRoleRequest)=call("api/v1/mobile/employees","PATCH",json.encodeToString(request))
 suspend fun setEmployeeActive(employeeId:String,isActive:Boolean)=call("api/v1/mobile/employees","PATCH",json.encodeToString(EmployeeActiveRequest(employeeId,isActive)))
 suspend fun branches()=json.decodeFromString<List<BranchDetails>>(call("api/v1/mobile/branches"))
 suspend fun createBranch(name:String,code:String,address:String?,city:String?,state:String?,postal:String?,country:String?,phone:String?,email:String?)=call("api/v1/mobile/branches","POST",buildJsonObject{put("name",name);put("code",code);address?.let{put("addressLine1",it)};city?.let{put("city",it)};state?.let{put("state",it)};postal?.let{put("postalCode",it)};country?.let{put("country",it)};phone?.let{put("phone",it)};email?.let{put("email",it)}}.toString())
 suspend fun editBranch(branch:BranchDetails)=call("api/v1/mobile/branches","PATCH",buildJsonObject{put("branchId",branch.id);put("name",branch.name);put("code",branch.code);branch.addressLine1?.let{put("addressLine1",it)};branch.city?.let{put("city",it)};branch.state?.let{put("state",it)};branch.postalCode?.let{put("postalCode",it)};branch.country?.let{put("country",it)};branch.phone?.let{put("phone",it)};branch.email?.let{put("email",it)}}.toString())
 suspend fun setBranchActive(id:String,active:Boolean)=call("api/v1/mobile/branches","PATCH",buildJsonObject{put("action","SET_ACTIVE");put("branchId",id);put("isActive",active)}.toString())
 suspend fun customerAdmin()=json.decodeFromString<CustomerAdminContext>(call("api/v1/mobile/customers"))
 suspend fun createCustomer(request:CreateCustomerRequest)=call("api/v1/mobile/customers","POST",json.encodeToString(request))
 suspend fun assignCustomer(request:AssignCustomerRequest)=call("api/v1/mobile/customers","POST",json.encodeToString(request))
 suspend fun fieldContext()=json.decodeFromString<FieldContext>(call("api/v1/mobile/field"));suspend fun followUps(status:String,employeeId:String?=null)=json.decodeFromString<FollowUpsContext>(call("api/v1/mobile/follow-ups?status=${enc(status)}${employeeId?.let{"&employeeId=${enc(it)}"}.orEmpty()}"));suspend fun cancelFollowUp(taskId:String)=call("api/v1/mobile/follow-ups","POST",json.encodeToString(buildJsonObject{put("action","CANCEL");put("taskId",taskId)}))
 suspend fun checkIn(visitType:String,subjectId:String?,name:String?,phone:String?,location:LocationPayload,notes:String?,photo:ByteArray?,followUpTaskId:String?=null)=withContext(Dispatchers.IO){val body=MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("action","CHECK_IN").addFormDataPart("visitType",visitType).addFormDataPart("latitude",location.latitude.toString()).addFormDataPart("longitude",location.longitude.toString()).addFormDataPart("accuracyMeters",(location.accuracyMeters?:0.0).toString()).apply{notes?.let{addFormDataPart("visitNotes",it)};name?.let{addFormDataPart("name",it)};phone?.let{addFormDataPart("phone",it)};subjectId?.let{addFormDataPart(if(visitType=="CUSTOMER")"customerId" else "leadId",it)};followUpTaskId?.let{addFormDataPart("followUpTaskId",it)};photo?.let{addFormDataPart("photo","photo.webp",it.toRequestBody("image/webp".toMediaType()))}}.build();val requestToken=session.token();val request=Request.Builder().url(BuildConfig.API_BASE_URL+"api/v1/mobile/field").header("Accept","application/json").apply{requestToken?.let{header("Authorization","Bearer $it")}}.post(body).build();http.newCall(request).execute().use{val raw=it.body?.string()?:"{}";if(!it.isSuccessful){if(it.code==401)session.invalidateIfCurrent(requestToken);val code=runCatching{json.parseToJsonElement(raw).jsonObject["error"]?.jsonPrimitive?.content}.getOrNull();if(it.code==403&&code=="FORBIDDEN")session.authorizationChanged();val distance=runCatching{json.parseToJsonElement(raw).jsonObject["distanceMeters"]?.jsonPrimitive?.content?.toDouble()}.getOrNull();throw ApiException(it.code,code,distance)};raw}}
 suspend fun checkout(visitId:String,location:LocationPayload,sentiment:VisitSentiment,remarks:String?)=call("api/v1/mobile/field","POST",json.encodeToString(CheckoutRequest(visitId=visitId,location=location,sentiment=sentiment,remarks=remarks)))
 suspend fun leads(q:String?=null,employeeId:String?=null)=json.decodeFromString<List<LeadSummary>>(call("api/v1/mobile/leads"+buildList{q?.takeIf{it.isNotBlank()}?.let{add("q=${enc(it)}")};employeeId?.let{add("assignedUserId=${enc(it)}")}}.joinToString("&",prefix="?").takeIf{it!="?"}.orEmpty()))
 suspend fun leadOptions()=json.decodeFromString<List<DashboardEmployee>>(call("api/v1/mobile/leads?view=options"))
 suspend fun pendingLeads()=json.decodeFromString<PendingLeadsContext>(call("api/v1/mobile/leads?view=pending"));suspend fun addPendingPhone(visitId:String,phone:String)=call("api/v1/mobile/leads","POST",json.encodeToString(buildJsonObject{put("action","ADD_PENDING_PHONE");put("visitId",visitId);put("phone",phone)}));suspend fun lead(id:String)=json.decodeFromString<LeadSummary>(call("api/v1/mobile/leads?id=$id"));suspend fun leadFromVisit(visitId:String,title:String)=json.decodeFromString<LeadSummary>(call("api/v1/mobile/leads","POST",json.encodeToString(LeadFromVisitRequest(visitId=visitId,title=title))));suspend fun transitionLead(id:String,version:Int,stage:LeadStage,reason:String?)=call("api/v1/mobile/leads","POST",json.encodeToString(LeadTransitionRequest(leadId=id,version=version,toStage=stage,lostReason=reason)));suspend fun updateFollowUp(id:String,at:String?,notes:String?)=call("api/v1/mobile/leads","POST",json.encodeToString(LeadFollowUpRequest(leadId=id,followUpAt=at,notes=notes)));suspend fun editLead(request:LeadEditRequest)=json.decodeFromString<LeadSummary>(call("api/v1/mobile/leads","POST",json.encodeToString(request)));suspend fun deleteLead(id:String)=call("api/v1/mobile/leads","POST",json.encodeToString(buildJsonObject{put("action","DELETE");put("leadId",id)}))
 suspend fun report(type:String)=json.parseToJsonElement(call("api/v1/mobile/reports?type=$type")).jsonObject
 suspend fun report(type:String,start:String?,end:String?,employeeId:String?,customerId:String?=null,status:String="ALL",sentiment:String="ALL",page:Int=1):kotlinx.serialization.json.JsonObject{val parameters=mutableListOf("type=${enc(type)}","page=$page");if(type=="gps"&&start!=null)parameters.add("date=${enc(start)}")else{if(start!=null)parameters.add("start=${enc(start)}");if(end!=null)parameters.add("end=${enc(end)}")};employeeId?.let{parameters.add("employeeId=${enc(it)}")};customerId?.let{parameters.add("customerId=${enc(it)}")};if(status!="ALL")parameters.add("status=${enc(status)}");if(sentiment!="ALL")parameters.add("sentiment=${enc(sentiment)}");return json.parseToJsonElement(call("api/v1/mobile/reports?${parameters.joinToString("&")}")).jsonObject}
 suspend fun reportExcel(type:String,start:String?,end:String?,employeeId:String?,customerId:String?,status:String,sentiment:String):ByteArray=withContext(Dispatchers.IO){val parameters=mutableListOf<String>();if(type=="gps"&&start!=null)parameters.add("date=${enc(start)}")else{start?.let{parameters.add("start=${enc(it)}")};end?.let{parameters.add("end=${enc(it)}")}};employeeId?.let{parameters.add("employeeId=${enc(it)}")};customerId?.let{parameters.add("customerId=${enc(it)}")};if(status!="ALL")parameters.add("status=${enc(status)}");if(sentiment!="ALL")parameters.add("sentiment=${enc(sentiment)}");val exportType=if(type=="geofence")"geofence-breaches" else type;val requestToken=session.token();val request=Request.Builder().url(BuildConfig.API_BASE_URL+"api/v1/mobile/reports/${enc(exportType)}/excel${parameters.joinToString("&",prefix=if(parameters.isEmpty())"" else "?")}").header("Accept","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet").apply{requestToken?.let{header("Authorization","Bearer $it")}}.build();http.newCall(request).execute().use{response->if(!response.isSuccessful){if(response.code==401)session.invalidateIfCurrent(requestToken);if(response.code==403)session.authorizationChanged();throw ApiException(response.code,if(response.code==422)"REPORT_TOO_LARGE" else "EXPORT_FAILED")};response.body?.bytes()?:throw IOException("Empty export")}}
 suspend fun billing(page:Int=1)=json.decodeFromString<MobileBillingContext>(call("api/v1/mobile/billing?page=$page"));suspend fun billingQuote(request:BillingQuoteRequest)=json.decodeFromString<BillingQuote>(call("api/v1/mobile/billing","POST",json.encodeToString(request)));suspend fun createManualOrder(request:ManualOrderRequest)=json.decodeFromString<ManualOrderResponse>(call("api/v1/mobile/billing","POST",json.encodeToString(request)))
 suspend fun company()=json.decodeFromString<CompanyContext>(call("api/v1/mobile/company"));suspend fun updateOperations(data:OperationsSettings)=json.decodeFromString<CompanyContext>(call("api/v1/mobile/company","PATCH",json.encodeToString(CompanyUpdateRequest("operations",data))));suspend fun updateGeofence(data:GeofenceSettings)=json.decodeFromString<CompanyContext>(call("api/v1/mobile/company","PATCH",json.encodeToString(CompanyUpdateRequest("geofence",data))));suspend fun updateTravel(data:TravelRateSettings)=json.decodeFromString<CompanyContext>(call("api/v1/mobile/company","PATCH",json.encodeToString(CompanyUpdateRequest("travel",data))));suspend fun targets()=json.decodeFromString<TargetsContext>(call("api/v1/mobile/targets"));suspend fun monthlyTargets()=json.decodeFromString<MonthlyTargetsContext>(call("api/v1/mobile/targets?view=monthly"));suspend fun saveMonthlyTarget(data:MonthlyTargetSaveRequest)=json.decodeFromString<MonthlyTargetsContext>(call("api/v1/mobile/targets","POST",json.encodeToString(data)));suspend fun createTarget(data:TargetRequest)=json.decodeFromString<TargetsContext>(call("api/v1/mobile/targets","POST",json.encodeToString(data)));suspend fun editTarget(data:EditTargetRequest)=json.decodeFromString<TargetsContext>(call("api/v1/mobile/targets","PATCH",json.encodeToString(data)))
}
class ApiException(val status:Int,val code:String?=null,val distanceMeters:Double?=null):Exception("API request failed")
class ForbiddenMobileRoleException:Exception("Mobile role is not allowed")
